parameterdescription.para:
マスク生成機能 Example ret=wc_InitRsaKey(&key,NULL);
if(ret==0){
ret=wc_InitRng(&rng);
}elsereturn-1;
if(ret==0){
ret=wc_RsaSetRNG(&key,&rng);
}elsereturn-1;
if(ret==0){
ret=wc_MakeRsaKey(&key,2048,WC_RSA_EXPONENT,&rng);
}elsereturn-1;

if(ret==0){
digestSz=wc_HashGetDigestSize(WC_HASH_TYPE_SHA256);
ret=wc_Hash(WC_HASH_TYPE_SHA256,message,sz,digest,digestSz);
}elsereturn-1;

if(ret==0){
ret=wc_RsaPSS_Sign(digest,digestSz,pSignature,pSignatureSz,
WC_HASH_TYPE_SHA256,WC_MGF1SHA256,&key,&rng);
if(ret>0){
sz=ret;
}elsereturn-1;
}elsereturn-1;
if(ret==0){
ret=wc_RsaPSS_VerifyCheck(pSignature,sz,pt,outLen,
digest,digestSz,WC_HASH_TYPE_SHA256,WC_MGF1SHA256,&key);
if(ret<=0)return-1;
}elsereturn-1;

wc_FreeRsaKey(&key);
wc_FreeRng(&rng);

使用される塩の長さ。RSA_PSSS_SALT_LEN_DEFAULT（-1）塩の長さはハッシュ長と同じです。RSA_PSS_SALT_LEN_DISCOVERは、塩の長さがデータから決定されます。 Example ret=wc_InitRsaKey(&key,NULL);
if(ret==0){
ret=wc_InitRng(&rng);
}elsereturn-1;
if(ret==0){
ret=wc_RsaSetRNG(&key,&rng);
}elsereturn-1;
if(ret==0){
ret=wc_MakeRsaKey(&key,2048,WC_RSA_EXPONENT,&rng);
}elsereturn-1;

if(ret==0){
digestSz=wc_HashGetDigestSize(WC_HASH_TYPE_SHA256);
ret=wc_Hash(WC_HASH_TYPE_SHA256,message,sz,digest,digestSz);
}elsereturn-1;

if(ret==0){
ret=wc_RsaPSS_Sign(digest,digestSz,pSignature,pSignatureSz,
WC_HASH_TYPE_SHA256,WC_MGF1SHA256,&key,&rng);
if(ret>0){
sz=ret;
}elsereturn-1;
}elsereturn-1;
if(ret==0){
ret=wc_RsaPSS_VerifyCheck_ex(pSignature,sz,pt,outLen,
digest,digestSz,WC_HASH_TYPE_SHA256,WC_MGF1SHA256,saltLen,&key);
if(ret<=0)return-1;
}elsereturn-1;

wc_FreeRsaKey(&key);
wc_FreeRng(&rng);

