//generate2048bitlongprivatekey
ret=wc_MakeRsaKey(&priv,2048,e,&rng);
if(ret!=0){
//errorgeneratingprivatekey
}

RSAキー構造 Example intret,count=0;
RsaKeykey;
RsaNbnb;

wc_InitRsaKey(&key,NULL);

//Enablenon-blockingRSAmode-providecontext
ret=wc_RsaSetNonBlock(key,&nb);
if(ret!=0)
returnret;

do{
ret=wc_RsaSSL_Sign(in,inLen,out,outSz,key,rng);
count++;//tracknumberofwouldblocks
if(ret==FP_WOULDBLOCK){
//do"other"workhere
}
}while(ret==FP_WOULDBLOCK);
if(ret<0){
returnret;
}

printf("RSAnon-blocksign:size%d,%dtimes\n",ret,count);

マイクロ秒をブロックする最大時間。 Example RsaKeykey;
RsaNbnb;

wc_InitRsaKey(&key,NULL);
wc_RsaSetNonBlock(key,&nb);
wc_RsaSetNonBlockTime(&key,4000,160);//BlockMax=4ms,CPU=160MHz
